            if visited[node]:
                return 0
            visited[node] = True
            max_depth = 0
            for neighbor in range(n):
                if graph[node][neighbor] == 1:
                    depth = dfs(neighbor)
                    if depth > max_depth:
                        max_depth = depth
            stack.append(node)
            return max_depth + 1

        for node in range(n):
            dfs(node)

        return len(stack) - n

